<?php
declare(strict_types=1);
namespace WexaShelf;
use PDO;

/** Structured, cited facts for decision tools. Missing observations remain unknown. */
final class Capabilities {
    public const FIELDS=['quotas','formats','availability','privacy','migrations'];
    public function __construct(private PDO $db,private Repository $repo){}
    public static function empty(string $id,int $sourceRevision=0):array{return ['appId'=>$id,'revision'=>0,'sourceRevision'=>$sourceRevision,'sourceFingerprint'=>'','updatedAt'=>'','quotas'=>[],'formats'=>[],'availability'=>[],'privacy'=>[],'migrations'=>[],'changes'=>[]];}
    private static function text(mixed $v,string $key,int $max=500):void{Validation::str($v,$key,$max);Validation::check(trim($v)!=='',"$key is required.");}
    private static function proof(array $row):void{Validation::url($row['sourceUrl']??null);Validation::date($row['checkedAt']??null);Validation::check(strtotime($row['checkedAt'])<=time()+300,'Evidence cannot be dated in the future.');}
    private static function notes(mixed $notes):void{Validation::check(is_array($notes)&&count($notes)<=24&&isset($notes['en']),'English evidence notes are required.');foreach($notes as $locale=>$text){Validation::check(is_string($locale)&&preg_match('/^[a-z]{2,3}(?:-[A-Z]{2})?$/D',$locale),'Invalid note language.');self::text($text,'Evidence note',2000);}}
    private static function state(mixed $state):void{Validation::check(in_array($state,['supported','limited','unsupported','unknown'],true),'Invalid evidence state.');}
    public static function validate(mixed $v):array {
        Validation::check(is_array($v)&&!array_diff(array_keys($v),['appId','revision','sourceRevision','sourceFingerprint','updatedAt','quotas','formats','availability','privacy','migrations','changes','stale']),'Unknown capability fields.');
        Validation::check(is_string($v['appId']??null)&&preg_match('/^[a-z0-9][a-z0-9-]{0,79}$/D',$v['appId']),'Invalid app ID.');foreach(['revision','sourceRevision'] as $key)Validation::check(is_int($v[$key]??null)&&$v[$key]>=0&&$v[$key]<2147483647,'Invalid revision.');
        foreach(self::FIELDS as $field){$seen=[];foreach(Validation::items($v[$field]??null,$field,100) as $row){Validation::check(is_array($row),'Invalid observation.');self::proof($row);
            $keys=match($field){'quotas'=>['planId','metric','limit','unit','period','scope','platform','sourceUrl','checkedAt'],'formats'=>['extension','modes','platform','sourceUrl','checkedAt'],'availability'=>['platform','country','minOs','devices','state','sourceUrl','checkedAt'],'privacy'=>['key','state','notes','sourceUrl','checkedAt'],'migrations'=>['toAppId','dimension','state','notes','sourceUrl','checkedAt']};Validation::check(!array_diff(array_keys($row),$keys)&&!array_diff($keys,array_keys($row)),'Unexpected or missing observation fields.');
            if(in_array($field,['quotas','formats','availability'],true))Validation::check(in_array($row['platform'],Validation::PLATFORMS,true),'Invalid observation platform.');
            if($field==='quotas'){self::text($row['planId'],'Plan ID',80);Validation::check(in_array($row['metric'],['ocr-pages','storage-mb','projects','members','upload-mb','automation-runs'],true)&&in_array($row['unit'],['pages','mb','count'],true)&&in_array($row['period'],['month','day','total'],true)&&in_array($row['scope'],['account','seat'],true),'Invalid quota dimensions.');Validation::check($row['limit']===null||(is_int($row['limit'])||is_float($row['limit']))&&is_finite((float)$row['limit'])&&$row['limit']>=0&&$row['limit']<=9007199254740991,'Invalid quota; null means unknown, never unlimited.');Validation::check($row['unit']===match($row['metric']){'ocr-pages'=>'pages','storage-mb','upload-mb'=>'mb',default=>'count'},'Quota unit does not match the metric.');$identity=$row['planId'].':'.$row['platform'].':'.$row['metric'].':'.$row['period'].':'.$row['scope'];}
            elseif($field==='formats'){Validation::check(is_string($row['extension'])&&preg_match('/^[a-z0-9]{1,12}$/D',$row['extension']),'Invalid file extension.');$modes=Validation::items($row['modes'],'modes',4);Validation::check($modes&&count(array_unique($modes))===count($modes)&&!array_diff($modes,['open','edit','import','export']),'Invalid file operations.');$identity=$row['extension'].':'.$row['platform'];}
            elseif($field==='availability'){Validation::check(Validation::country($row['country']),'Invalid country.');Validation::str($row['minOs'],'Minimum OS',100);foreach(Validation::items($row['devices'],'devices',20) as $device)self::text($device,'Device',80);self::state($row['state']);$identity=$row['platform'].':'.$row['country'];}
            elseif($field==='privacy'){Validation::check(in_array($row['key'],['account','ads','tracking','local-storage','export'],true),'Invalid privacy fact.');self::state($row['state']);self::notes($row['notes']);$identity=$row['key'];}
            else{Validation::check(is_string($row['toAppId'])&&preg_match('/^[a-z0-9][a-z0-9-]{0,79}$/D',$row['toAppId'])&&$row['toAppId']!==$v['appId']&&in_array($row['dimension'],['notes','attachments','tags','links','history','tasks'],true),'Invalid migration target or dimension.');self::state($row['state']);self::notes($row['notes']);$identity=$row['toAppId'].':'.$row['dimension'];}
            Validation::check(!isset($seen[$identity]),'Duplicate observation.');$seen[$identity]=true;
        }}unset($v['stale']);return $v;
    }
    private function records():array{$out=[];foreach($this->repo->allRecords() as $r)if($r['kind']==='app')$out[$r['id']]=$r;return $out;}
    public function all():array{$out=[];$q=$this->db->query("SELECT value FROM ws_settings WHERE setting_key LIKE 'capabilities:%'");foreach($q->fetchAll() as $row){$v=json_decode($row['value'],true,64,JSON_THROW_ON_ERROR);$out[$v['appId']]=$v;}return $out;}
    public function stateData():array{$records=$this->records();$all=$this->all();foreach($all as $id=>&$v)$v['stale']=!isset($records[$id])||!hash_equals($v['sourceFingerprint'],Translations::fingerprint($records[$id]['data']));return ['records'=>array_values($records),'capabilities'=>$all,'proposals'=>$this->repo->setting('capability-proposals',[])];}
    public function save(array $input):array{
        $v=self::validate($input);return $this->repo->transaction(function()use($v){$records=$this->records();$source=$records[$v['appId']]??null;Validation::check($source,'Source app not found.');if($source['revision']!==$v['sourceRevision'])throw new ApiException('Source app changed. Review the latest version.',409);$old=$this->repo->setting('capabilities:'.$v['appId'],self::empty($v['appId']));if($old['revision']!==$v['revision'])throw new ApiException('Observations changed. Reload before saving.',409);
            $plans=array_column($source['data']['plans'],'id');foreach($v['quotas'] as $quota)Validation::check(in_array($quota['planId'],$plans,true)&&in_array($quota['platform'],$source['data']['platforms'],true),'Quota plan or platform is not in the app record.');foreach($v['migrations'] as $migration)Validation::check(isset($records[$migration['toAppId']]),'Migration target app not found.');
            $changed=[];foreach(self::FIELDS as $field)if($old[$field]!==$v[$field])$changed[]=$field;$v['revision']++;$v['sourceFingerprint']=Translations::fingerprint($source['data']);$v['updatedAt']=Repository::now();$v['changes']=$old['changes']??[];
            if($changed)$v['changes'][]=['id'=>$v['appId'].'-'.$v['revision'],'at'=>$v['updatedAt'],'summary'=>['en'=>'Reviewed observations updated: '.implode(', ',$changed),'tr'=>'Kaynaklı gözlemler güncellendi: '.implode(', ',$changed)],'fields'=>$changed];$v['changes']=array_slice($v['changes'],-100);$this->repo->setSetting('capabilities:'.$v['appId'],$v);$this->repo->audit('capabilities-save',$v['appId'],'revision='.$v['revision']);return $v;
        });
    }
    public function publicData(array $apps):array{$out=[];foreach($apps as $app){$v=$this->repo->setting('capabilities:'.$app['id']);if(!$v)continue;$v['stale']=!hash_equals($v['sourceFingerprint'],Translations::fingerprint($app));$out[$app['id']]=$v;}return$out;}
    public function propose(array $input):array{
        Validation::check(empty($input['website']),'Invalid submission.');self::text($input['appId']??null,'App ID',80);self::text($input['summary']??null,'Summary',2000);Validation::url($input['sourceUrl']??null);$visible=array_column($this->repo->getPublicSnapshot()['apps'],'id');Validation::check(in_array($input['appId'],$visible,true),'Published app not found.');
        return $this->repo->transaction(function()use($input){$rows=$this->repo->setting('capability-proposals',[]);Validation::check(count($rows)<1000,'The proposal queue is full.');$id=bin2hex(random_bytes(16));$rows[]=['id'=>$id,'appId'=>$input['appId'],'summary'=>$input['summary'],'sourceUrl'=>$input['sourceUrl'],'createdAt'=>Repository::now(),'status'=>'pending'];$this->repo->setSetting('capability-proposals',$rows);return ['id'=>$id,'status'=>'pending'];});
    }
    public function reviewProposal(array $input):array{
        Validation::check(is_string($input['id']??null)&&in_array($input['status']??null,['reviewed','dismissed'],true),'Invalid review.');return $this->repo->transaction(function()use($input){$rows=$this->repo->setting('capability-proposals',[]);$found=false;foreach($rows as &$row)if($row['id']===$input['id']){$found=true;$row['status']=$input['status'];$row['reviewedAt']=Repository::now();}unset($row);Validation::check($found,'Proposal not found.');$this->repo->setSetting('capability-proposals',$rows);$this->repo->audit('proposal-review',$input['id'],$input['status']);return ['proposals'=>$rows];});
    }
    public function backup():array{return ['records'=>array_values($this->all()),'proposals'=>$this->repo->setting('capability-proposals',[])];}
    public static function validateBackup(mixed $b):array{
        if($b===null)return ['records'=>[],'proposals'=>[]];Validation::check(is_array($b),'Invalid capability backup.');$out=['records'=>[],'proposals'=>[]];$seen=[];foreach(Validation::items($b['records']??null,'records',100000) as $raw){$v=self::validate($raw);Validation::check(!isset($seen[$v['appId']])&&$v['revision']>0&&is_string($v['sourceFingerprint']??null)&&preg_match('/^[a-f0-9]{64}$/D',$v['sourceFingerprint']),'Invalid observation version.');$seen[$v['appId']]=true;Validation::date($v['updatedAt']??null);foreach(Validation::items($v['changes']??[],'changes',100) as $change){self::text($change['id']??null,'Change ID',120);Validation::date($change['at']??null);self::notes($change['summary']??null);Validation::check(!array_diff(Validation::items($change['fields']??null,'fields',5),self::FIELDS),'Invalid change fields.');}$out['records'][]=$v;}
        $proposalIds=[];foreach(Validation::items($b['proposals']??null,'proposals',1000) as $p){foreach(['id'=>64,'appId'=>80,'summary'=>2000] as $key=>$max)self::text($p[$key]??null,$key,$max);Validation::url($p['sourceUrl']??null);Validation::date($p['createdAt']??null);Validation::check(in_array($p['status']??null,['pending','reviewed','dismissed'],true),'Invalid proposal status.');Validation::check(!isset($proposalIds[$p['id']]),'Duplicate proposal ID.');$proposalIds[$p['id']]=true;$out['proposals'][]=$p;}return $out;
    }
    public function restoreBackup(array $b):void{$b=self::validateBackup($b);$this->db->exec("DELETE FROM ws_settings WHERE setting_key LIKE 'capabilities:%'");foreach($b['records'] as $v)$this->repo->setSetting('capabilities:'.$v['appId'],$v);$this->repo->setSetting('capability-proposals',$b['proposals']);}
}
